fn keyword(text: &str) -> TokenKind {
    match text {
        "break" => KW_BREAK,
        "case" => KW_CASE,
        "chan" => KW_CHAN,
        "const" => KW_CONST,
        "continue" => KW_CONTINUE,
        "default" => KW_DEFAULT,
        "defer" => KW_DEFER,
        "else" => KW_ELSE,
        "fallthrough" => KW_FALLTHROUGH,
        "false" => KW_FALSE,
        "for" => KW_FOR,
        "func" => KW_FUNC,
        "go" => KW_GO,
        "goto" => KW_GOTO,
        "if" => KW_IF,
        "import" => KW_IMPORT,
        "interface" => KW_INTERFACE,
        "iota" => KW_IOTA,
        "make" => KW_MAKE,
        "map" => KW_MAP,
        "new" => KW_NEW,
        "nil" => KW_NIL,
        "package" => KW_PACKAGE,
        "range" => KW_RANGE,
        "return" => KW_RETURN,
        "select" => KW_SELECT,
        "struct" => KW_STRUCT,
        "switch" => KW_SWITCH,
        "true" => KW_TRUE,
        "type" => KW_TYPE,
        "var" => KW_VAR,
        _ => IDENTIFIER,
    }
}
fn punctuation(remainder: &str) -> Option<(usize, TokenKind)> {
    match remainder.as_bytes().first().copied()? {
        0x21 => {
            if remainder.starts_with("!=") {
                return Some((2, PUNCT_21_3D));
            }
            if remainder.starts_with("!") {
                return Some((1, PUNCT_21));
            }
        }
        0x25 => {
            if remainder.starts_with("%=") {
                return Some((2, PUNCT_25_3D));
            }
            if remainder.starts_with("%") {
                return Some((1, PUNCT_25));
            }
        }
        0x26 => {
            if remainder.starts_with("&^=") {
                return Some((3, PUNCT_26_5E_3D));
            }
            if remainder.starts_with("&&") {
                return Some((2, PUNCT_26_26));
            }
            if remainder.starts_with("&=") {
                return Some((2, PUNCT_26_3D));
            }
            if remainder.starts_with("&^") {
                return Some((2, PUNCT_26_5E));
            }
            if remainder.starts_with("&") {
                return Some((1, PUNCT_26));
            }
        }
        0x28 => {
            if remainder.starts_with("(") {
                return Some((1, PUNCT_28));
            }
        }
        0x29 => {
            if remainder.starts_with(")") {
                return Some((1, PUNCT_29));
            }
        }
        0x2A => {
            if remainder.starts_with("*=") {
                return Some((2, PUNCT_2A_3D));
            }
            if remainder.starts_with("*") {
                return Some((1, PUNCT_2A));
            }
        }
        0x2B => {
            if remainder.starts_with("++") {
                return Some((2, PUNCT_2B_2B));
            }
            if remainder.starts_with("+=") {
                return Some((2, PUNCT_2B_3D));
            }
            if remainder.starts_with("+") {
                return Some((1, PUNCT_2B));
            }
        }
        0x2C => {
            if remainder.starts_with(",") {
                return Some((1, PUNCT_2C));
            }
        }
        0x2D => {
            if remainder.starts_with("--") {
                return Some((2, PUNCT_2D_2D));
            }
            if remainder.starts_with("-=") {
                return Some((2, PUNCT_2D_3D));
            }
            if remainder.starts_with("-") {
                return Some((1, PUNCT_2D));
            }
        }
        0x2E => {
            if remainder.starts_with("...") {
                return Some((3, PUNCT_2E_2E_2E));
            }
            if remainder.starts_with(".") {
                return Some((1, PUNCT_2E));
            }
        }
        0x2F => {
            if remainder.starts_with("/=") {
                return Some((2, PUNCT_2F_3D));
            }
            if remainder.starts_with("/") {
                return Some((1, PUNCT_2F));
            }
        }
        0x3A => {
            if remainder.starts_with(":=") {
                return Some((2, PUNCT_3A_3D));
            }
            if remainder.starts_with(":") {
                return Some((1, PUNCT_3A));
            }
        }
        0x3B => {
            if remainder.starts_with(";") {
                return Some((1, PUNCT_3B));
            }
        }
        0x3C => {
            if remainder.starts_with("<<=") {
                return Some((3, PUNCT_3C_3C_3D));
            }
            if remainder.starts_with("<-") {
                return Some((2, PUNCT_3C_2D));
            }
            if remainder.starts_with("<<") {
                return Some((2, PUNCT_3C_3C));
            }
            if remainder.starts_with("<=") {
                return Some((2, PUNCT_3C_3D));
            }
            if remainder.starts_with("<") {
                return Some((1, PUNCT_3C));
            }
        }
        0x3D => {
            if remainder.starts_with("==") {
                return Some((2, PUNCT_3D_3D));
            }
            if remainder.starts_with("=") {
                return Some((1, PUNCT_3D));
            }
        }
        0x3E => {
            if remainder.starts_with(">>=") {
                return Some((3, PUNCT_3E_3E_3D));
            }
            if remainder.starts_with(">=") {
                return Some((2, PUNCT_3E_3D));
            }
            if remainder.starts_with(">>") {
                return Some((2, PUNCT_3E_3E));
            }
            if remainder.starts_with(">") {
                return Some((1, PUNCT_3E));
            }
        }
        0x5B => {
            if remainder.starts_with("[") {
                return Some((1, PUNCT_5B));
            }
        }
        0x5C => {
            if remainder.starts_with("\\") {
                return Some((1, PUNCT_5C));
            }
        }
        0x5D => {
            if remainder.starts_with("]") {
                return Some((1, PUNCT_5D));
            }
        }
        0x5E => {
            if remainder.starts_with("^=") {
                return Some((2, PUNCT_5E_3D));
            }
            if remainder.starts_with("^") {
                return Some((1, PUNCT_5E));
            }
        }
        0x7B => {
            if remainder.starts_with("{") {
                return Some((1, PUNCT_7B));
            }
        }
        0x7C => {
            if remainder.starts_with("|=") {
                return Some((2, PUNCT_7C_3D));
            }
            if remainder.starts_with("||") {
                return Some((2, PUNCT_7C_7C));
            }
            if remainder.starts_with("|") {
                return Some((1, PUNCT_7C));
            }
        }
        0x7D => {
            if remainder.starts_with("}") {
                return Some((1, PUNCT_7D));
            }
        }
        0x7E => {
            if remainder.starts_with("~") {
                return Some((1, PUNCT_7E));
            }
        }
        _ => {}
    }
    None
}
fn item(len: usize, kind: TokenKind, skip: bool, error: bool) -> GeneratedLexeme {
    GeneratedLexeme {
        len,
        kind,
        skip,
        error,
    }
}
fn lex(source: &str, at: usize) -> GeneratedLexeme {
    let rest = &source[at..];
    let bytes = rest.as_bytes();
    let mut best: (usize, i32, TokenKind, bool) = (0, i32::MIN, UNKNOWN, false);
    for m in MACHINES {
        let mut state = 0usize;
        for (n, &byte) in bytes.iter().enumerate() {
            state = m.trans[state * m.class_count + m.classes[byte as usize] as usize] as usize;
            if m.dead[state] {
                break;
            }
            if m.accept[state] {
                let len = n + 1;
                if len > best.0 || (len == best.0 && m.priority > best.1) {
                    best = (len, m.priority, m.kind, m.skip)
                }
            }
        }
    }
    if best.0 == 0 {
        for m in MACHINES {
            if let Some((delimiter, newline)) = m.recovery {
                if bytes.first() == Some(&delimiter) {
                    let mut n = 1;
                    while n < bytes.len() && bytes[n] != delimiter && (newline || bytes[n] != b'\n')
                    {
                        n += 1
                    }
                    if n < bytes.len() && bytes[n] == delimiter {
                        n += 1
                    }
                    return item(n, m.kind, m.skip, true);
                }
            }
        }
    }
    if best.0 == 0 {
        for m in MACHINES {
            if m.recovery_prefixes
                .iter()
                .any(|prefix| bytes.starts_with(prefix))
            {
                return item(bytes.len(), m.kind, m.skip, true);
            }
        }
    }
    if let Some((len, kind)) = punctuation(rest) {
        if len > best.0 {
            best = (len, 0, kind, false)
        }
    }
    if best.0 > 0 {
        let kind = if best.2 == IDENTIFIER {
            keyword(&rest[..best.0])
        } else {
            best.2
        };
        return item(best.0, kind, best.3, false);
    }
    let ch = rest.chars().next().unwrap();
    item(ch.len_utf8(), UNKNOWN, false, true)
}
pub fn scan<E: ExternalLexer>(source: &str) -> Result<TokenStream, String> {
    crate::parser::linear_scanner::scan::<E, Lexicon>(source)
}
